import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'min': 9.0, 'span': 5.0, 'ratio': 1.5})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 3, 'min': 25, 'span': 25.0, 'ratio': 1.5})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'min': 25.0, 'span': 29.0, 'ratio': 1.5})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'min': 0, 'span': 0, 'ratio': 0.0})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'min': 25, 'span': 26.0, 'ratio': 1.5})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'min': 0.0, 'span': 0.0, 'ratio': 0.5})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'min': 25, 'span': 75, 'ratio': 2.0})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 2, 'min': 4.0, 'span': 25.0, 'ratio': 1.0})

if __name__ == '__main__':
    unittest.main()
